static inline void *sCritterMoveNode(Critter *c, s32 nodeIndex)
{
    void *node;

    node = c->anim;
    if (nodeIndex < 0) {
        return node;
    }
    {
        void *candidate = ((void **)((u8 *)c->anodes + nodeIndex * 0x28))[0];

        if (candidate == NULL) {
            candidate = node;
        }
        return candidate;
    }
}

